namespace Reforged.App.Services;
public sealed class WorkspaceManager(IErrorReporter errors) : IWorkspaceManager { private readonly Dictionary<string,IWorkspace> _items=new(StringComparer.OrdinalIgnoreCase); public IReadOnlyCollection<IWorkspace> Workspaces=>_items.Values; public IWorkspace? ActiveWorkspace{get;private set;} public event EventHandler? ActiveWorkspaceChanged; public void Register(IWorkspace workspace)=>_items.Add(workspace.Id,workspace); public async Task ActivateAsync(string id,CancellationToken token=default){if(!_items.TryGetValue(id,out var next))throw new KeyNotFoundException($"Workspace '{id}' is not registered."); if(ReferenceEquals(next,ActiveWorkspace))return; try{if(ActiveWorkspace is not null)await ActiveWorkspace.DeactivateAsync(token);await next.ActivateAsync(token);ActiveWorkspace=next;ActiveWorkspaceChanged?.Invoke(this,EventArgs.Empty);}catch(Exception e){errors.Report(e,$"Workspace activation failed: {id}");throw;}} public async Task CloseAsync(string id,CancellationToken token=default){if(!_items.TryGetValue(id,out var item)||!item.CanClose)return;if(ReferenceEquals(item,ActiveWorkspace)){await item.DeactivateAsync(token);ActiveWorkspace=null;ActiveWorkspaceChanged?.Invoke(this,EventArgs.Empty);}} }
public sealed class Workspace(string id,string title,object view,bool canClose=false) : IWorkspace { public string Id=>id;public string Title=>title;public object View=>view;public bool CanClose=>canClose;public Task ActivateAsync(CancellationToken token)=>Task.CompletedTask;public Task DeactivateAsync(CancellationToken token)=>Task.CompletedTask; }
